\set ON_ERROR_STOP on
BEGIN;
SELECT set_config('request.jwt.claim.sub','ab5a48c0-939b-4502-bd3b-db7801f0f8b8',true);
CREATE TEMP TABLE pe_fixture(k text PRIMARY KEY,id uuid);
INSERT INTO pe_fixture VALUES ('project',gen_random_uuid()),('project2',gen_random_uuid()),('payer',gen_random_uuid()),('bank',gen_random_uuid()),('client',gen_random_uuid());
INSERT INTO companies(id,nome,is_client) SELECT id,'[DISPOSABLE EXPENSE FIXTURE] client',true FROM pe_fixture WHERE k='client';
INSERT INTO pm_projects(id,name,status,company_id) SELECT id,'[DISPOSABLE EXPENSE FIXTURE] '||k,'active',(SELECT id FROM pe_fixture WHERE k='client') FROM pe_fixture WHERE k IN ('project','project2');
INSERT INTO collaborators(id,nome,email) SELECT id,'[DISPOSABLE EXPENSE FIXTURE] payer','pe-fixture@example.invalid' FROM pe_fixture WHERE k='payer';
INSERT INTO bank_accounts(id,account_name,entity_id) SELECT id,'[DISPOSABLE EXPENSE FIXTURE] bank','00000000-0000-4000-a000-000000000001' FROM pe_fixture WHERE k='bank';
DO $$ DECLARE p uuid:=(SELECT id FROM pe_fixture WHERE k='project'); p2 uuid:=(SELECT id FROM pe_fixture WHERE k='project2'); c uuid:=(SELECT id FROM pe_fixture WHERE k='payer'); e uuid; e2 uuid; r jsonb; b uuid; tx uuid; inv uuid; cr uuid; ia uuid; pay uuid; ra uuid; hdr jsonb; cost numeric; BEGIN
r:=pe_action('save',jsonb_build_object('projectId',p,'description','[DISPOSABLE EXPENSE FIXTURE] GBP taxi','currency','GBP','originalAmount',100,'eurAmount','120','exchangeDate','2026-11-02','exchangeSource','fixture evidence','exchangeEvidence',jsonb_build_object('reference','fixture-fx'),'paidBy','personal','collaboratorId',c,'rebillMode','markup','markupPct',20,'taxTreatment','reinvoiced_cost','taxParameters',jsonb_build_object('vatRate',23),'intakeKey','fixture-completion-key')); e:=(r->>'id')::uuid;
IF (SELECT eur_amount FROM pm_expenses WHERE id=e)<>120 THEN RAISE EXCEPTION 'GBP evidence failed'; END IF;
r:=pe_action('save',jsonb_build_object('intakeKey','fixture-completion-key')); IF (r->>'id')::uuid<>e THEN RAISE EXCEPTION 'Idempotence failed'; END IF;
IF EXISTS(SELECT 1 FROM finance_holder_reimbursements WHERE project_expense_id=e) THEN RAISE EXCEPTION 'Unapproved obligation'; END IF;
PERFORM pe_action('submit',jsonb_build_object('expenseId',e)); PERFORM pe_action('decide',jsonb_build_object('expenseId',e,'approve',false,'reason','fixture rejection')); IF (SELECT approval_state FROM pm_expenses WHERE id=e)<>'rejected' THEN RAISE EXCEPTION 'Rejection failed'; END IF;
PERFORM pe_action('submit',jsonb_build_object('expenseId',e)); PERFORM pe_action('decide',jsonb_build_object('expenseId',e,'approve',true));
e2:=(pe_action('save',jsonb_build_object('projectId',p2,'description','[DISPOSABLE EXPENSE FIXTURE] meal','currency','EUR','originalAmount',30,'paidBy','personal','collaboratorId',c,'rebillMode','cost'))->>'id')::uuid; PERFORM pe_action('submit',jsonb_build_object('expenseId',e2)); PERFORM pe_action('decide',jsonb_build_object('expenseId',e2,'approve',true));
b:=(pe_action('batch',jsonb_build_object('collaboratorId',c,'obligationIds',(SELECT jsonb_agg(id) FROM finance_holder_reimbursements WHERE project_expense_id IN(e,e2))))->>'id')::uuid;
IF (SELECT sum(reserved_amount) FROM project_reimbursement_allocations WHERE batch_id=b)<>150 THEN RAISE EXCEPTION 'Cross-project batch wrong'; END IF;
INSERT INTO bank_transactions(bank_account_id,entity_id,transaction_date,description,amount,row_checksum) VALUES((SELECT id FROM pe_fixture WHERE k='bank'),'00000000-0000-4000-a000-000000000001','2026-11-02','[DISPOSABLE EXPENSE FIXTURE] transfer',-75,gen_random_uuid()::text) RETURNING id INTO tx;
PERFORM pe_action('settleBatch',jsonb_build_object('batchId',b,'transactionId',tx,'amount',75)); IF fin_tx_open_balance(tx)<>0 THEN RAISE EXCEPTION 'Partial settlement failed'; END IF;
FOR ra IN SELECT id FROM project_reimbursement_allocations WHERE batch_id=b AND bank_transaction_id=tx LOOP PERFORM pe_action('reverseReimbursement',jsonb_build_object('allocationId',ra,'reason','fixture undo')); END LOOP;
IF fin_tx_open_balance(tx)<>75 THEN RAISE EXCEPTION 'Undo failed'; END IF;
hdr:=jsonb_build_object('doc_type','client_invoice','status','issued','issue_date','2026-11-02','document_number','FT FIXTURE/91001','series','FIXTURE','counterparty_client_id',(SELECT id FROM pe_fixture WHERE k='client'),'project_id',p);
inv:=pe_invoice_from_expenses(hdr,jsonb_build_array(jsonb_build_object('expense_id',e,'expense_cost',120,'sort_order',0)));
SELECT id INTO ia FROM project_expense_invoice_allocations WHERE expense_id=e;
IF (SELECT billed_amount FROM project_expense_invoice_allocations WHERE id=ia)<>144 OR (SELECT vat_amount FROM project_expense_invoice_allocations WHERE id=ia)<>33.12 THEN RAISE EXCEPTION 'Markup/VAT wrong'; END IF;
INSERT INTO financial_document_payments(document_id,amount,payment_date,method,created_by) VALUES(inv,88.56,'2026-11-02','bank_transfer',auth.uid()) RETURNING id INTO pay;
PERFORM pe_action('receipt',jsonb_build_object('allocationId',ia,'paymentId',pay,'amount',88.56));
IF (SELECT received_net_amount FROM pe_expense_settlement_figures(p) WHERE expense_id=e)<>72 THEN RAISE EXCEPTION 'Net receipt wrong'; END IF;
cr:=pe_invoice_from_expenses(hdr||jsonb_build_object('doc_type','client_credit_note','document_number','NC FIXTURE/91002','original_document_id',inv),jsonb_build_array(jsonb_build_object('credit_allocation_id',ia,'expense_cost',30,'sort_order',0)));
IF (SELECT credited_cost FROM pe_expense_settlement_figures(p) WHERE expense_id=e)<>30 THEN RAISE EXCEPTION 'Partial credit wrong'; END IF;
BEGIN PERFORM pe_action('receipt',jsonb_build_object('allocationId',ia,'paymentId',pay,'amount',88.56)); RAISE EXCEPTION 'Duplicate receipt admitted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='Duplicate receipt admitted' THEN RAISE; END IF; END;
BEGIN INSERT INTO pm_expenses(project_id,description,purchase_price) VALUES(p,'legacy bypass',1); RAISE EXCEPTION 'Legacy insert admitted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='Legacy insert admitted' THEN RAISE; END IF; END;
RAISE NOTICE 'PASS: GBP evidence, idempotent intake, no unapproved reimbursement, rejection/reapproval, cross-project batch, partial payment/undo, invoice line creation, markup, VAT, explicit net receipt, partial credit, duplicate receipt refusal, legacy insert refusal'; END $$;
ROLLBACK;
